Description: This Terraform configuration creates an AWS Lex V2 bot with multiple slots for a hotel booking workflow. The bot includes a custom slot type for room type, an intent with multiple required slots, a fallback intent, a bot version, and an alias. It also creates the IAM role required for AWS Lex to operate.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lex bot will be created."
  type        = string
  default     = "us-east-1"
}

variable "bot_name" {
  description = "Name of the Amazon Lex V2 bot."
  type        = string
  default     = "hotel-booking-bot"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "lex_bot_role" {
  name = "${var.bot_name}-lex-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "lex_bot
